    public function spatialPooling(input:Array<Float>, sparsity:Float):Array<Int> {
        var overlaps = [for (col in columns) col.overlap(input)];
        var threshold = 0.0;
        for (val in overlaps) threshold += val;
        threshold = threshold / overlaps.length * sparsity;

        var active = [];
        for (i in 0...overlaps.length) {
            if (overlaps[i] > threshold) active.push(i);
        }
        return active;
    }

