class Matrix {
    public var rows:Int;
    public var cols:Int;
    public var data:haxe.ds.Vector<haxe.ds.Vector<Float>>;

    public function new(rows:Int, cols:Int) {
        this.rows = rows;
        this.cols = cols;
        this.data = new haxe.ds.Vector<haxe.ds.Vector<Float>>(rows);
        for (i in 0...rows) {
            this.data[i] = new haxe.ds.Vector<Float>(cols);
            for (j in 0...cols) {
                this.data[i][j] = 0.0;
            }
        }
    }

    public static function random(rows:Int, cols:Int):Matrix {
        var m = new Matrix(rows, cols);
        for (i in 0...rows) {
            for (j in 0...cols) {
                m.data[i][j] = Math.random() * 2 - 1;
            }
        }
        return m;
    }

    public function multiply(other:Matrix):Matrix {
        var result = new Matrix(this.rows, other.cols);
        for (i in 0...this.rows) {
            for (j in 0...other.cols) {
                var sum = 0.0;
                for (k in 0...this.cols) {
                    sum += this.data[i][k] * other.data[k][j];
                }
                result.data[i][j] = sum;
            }
        }
        return result;
    }

    public function add(other:Matrix):Matrix {
        var result = new Matrix(this.rows, this.cols);
        for (i in 0...this.rows) {
            for (j in 0...this.cols) {
                result.data[i][j] = this.data[i][j] + other.data[i][j];
            }
        }
        return result;
    }

    public function scale(scalar:Float):Matrix {
        var result = new Matrix(this.rows, this.cols);
        for (i in 0...this.rows) {
            for (j in 0...this.cols) {
                result.data[i][j] = this.data[i][j] * scalar;
            }
        }
        return result;
    }
}

