            this.splineCoeffs[i] = new haxe.ds.Vector<Float>(grid + 1);
            for (j in 0...(grid + 1)) {
                this.splineCoeffs[i][j] = Math.random() * 0.01;
            }
        }

        this.biases = new haxe.ds.Vector<Float>(outputDim);
        for (i in 0...outputDim) {
            this.biases[i] = 0.0;
        }
    }

    public function bSplineBasis(x:Float, knots:haxe.ds.Vector<Float>, degree:Int):haxe.ds.Vector<Float> {
        if (degree == 0) {
            var basis = new haxe.ds.Vector<Float>(knots.length);
            for (i in 0...knots.length) {
                var k = knots[i];
                var nextK = (i < knots.length - 1) ? knots[i + 1] : k + 1.0;
                basis[i] = (x >= k && x < nextK) ? 1.0 : 0.0;
            }
            return basis;
        } else {
            var dropped = new haxe.ds.Vector<Float>(knots.length - 1);
            for (i in 0...knots.length - 1) {
                dropped[i] = knots[i + 1];
            }
            var left = bSplineBasis(x, dropped, degree - 1);
            var right = bSplineBasis(x, dropped, degree - 1);
            var firstK = knots[0];
            var lastK = knots[knots.length - 1];
            var denom = (lastK - firstK > 0.0) ? lastK - firstK : 1.0;
            var alpha = (x - firstK) / denom;

            var basis = new haxe.ds.Vector<Float>(left.length);
            for (i in 0...left.length) {
                basis[i] = alpha * left[i] + (1.0 - alpha) * right[i];
            }
            return basis;
        }
    }

    public function forward(input:haxe.ds.Vector<Float>):haxe.ds.Vector<Float> {
        var output = new haxe.ds.Vector<Float>(outputDim);

        for (i in 0...outputDim) {
            var sum = this.biases[i];
            for (j in 0...inputDim) {
                var x = Math.max(0.0, Math.min(1.0, input[j]));
                var knots = new haxe.ds.Vector<Float>(grid + 1);
                for (k in 0...(grid + 1)) {
                    knots[k] = k / grid;
                }
                var basis = bSplineBasis(x, knots, 3);
                var splineVal = 0.0;
                for (k in 0...Std.int(Math.min(basis.length, splineCoeffs[i].length))) {
                    splineVal += basis[k] * splineCoeffs[i][k];
                }
                sum += weights.data[i][j] * splineVal;
            }
            output[i] = Math.max(0, sum);
        }

        return output;
    }
}

class QuantumCircuit {
    public var numQubits:Int;
    public var gates:Array<String>;
    public var parameters:haxe.ds.Vector<Float>;

    public function new(numQubits:Int) {
        this.numQubits = numQubits;
        this.gates = [];
        this.parameters = new haxe.ds.Vector<Float>(numQubits * 3);
        for (i in 0...parameters.length) {
            this.parameters[i] = Math.random() * Math.PI * 2;
        }
    }

    public function simulate():haxe.ds.Vector<Complex> {
        var stateSize = Std.int(Math.pow(2, numQubits));
        var state = new haxe.ds.Vector<Complex>(stateSize);
        state[0] = new Complex(1.0, 0.0);
        for (i in 1...stateSize) {
            state[i] = new Complex(0.0, 0.0);
        }
        return state;
    }
}

class KANNetwork {
    public var layers:Array<KANLayer>;
