class Tokenizer {
    public var vocab:Map<String, Int>;
    public var reverseVocab:Map<Int, String>;
    public var vocabSize:Int;

    public function new() {
        vocab = new Map<String, Int>();
        reverseVocab = new Map<Int, String>();

        var chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,!?-";
        for (i in 0...chars.length) {
            var char = chars.charAt(i);
            vocab.set(char, i);
            reverseVocab.set(i, char);
        }
        this.vocabSize = chars.length;
    }

    public function encode(text:String):Array<Int> {
        var tokens = [];
        for (i in 0...text.length) {
            var char = text.charAt(i);
            if (vocab.exists(char)) {
                tokens.push(vocab.get(char));
            } else {
                tokens.push(vocab.get("?"));
            }
        }
        return tokens;
    }

    public function decode(tokens:Array<Int>):String {
        var result = "";
        for (token in tokens) {
            if (reverseVocab.exists(token)) {
                result += reverseVocab.get(token);
            } else {
                result += "?";
            }
        }
        return result;
    }

    public function embedTokens(tokens:Array<Int>, dim:Int):Array<KANToken> {
        var embedded = [];
        for (i in 0...tokens.length) {
            var emb = new haxe.ds.Vector<Float>(dim);
            var scale = 1.0 / Math.sqrt(dim * 5);
            var phase = Math.sin(i * scale);

            for (j in 0...dim) {
                emb[j] = phase * i * scale * Math.random();
            }

            embedded.push(new KANToken(tokens[i], emb));
        }
        return embedded;
    }
}

class Optimizer {
    public var learningRate:Float;
    public var beta1:Float;
    public var beta2:Float;
    public var epsilon:Float;
    public var m:Map<String, Matrix>;
    public var v:Map<String, Matrix>;
    public var t:Int;

    public function new(lr:Float) {
        this.learningRate = lr;
        this.beta1 = 0.9;
        this.beta2 = 0.999;
        this.epsilon = 1e-8;
        this.m = new Map<String, Matrix>();
        this.v = new Map<String, Matrix>();
        this.t = 0;
    }

    public function step(network:KANNetwork, gradients:KANNetwork):Void {
        this.t++;
        var lrT = learningRate * Math.sqrt(1 - Math.pow(beta2, t)) / (1 - Math.pow(beta1, t));

        for (i in 0...network.layers.length) {
            var layer = network.layers[i];
            var gradLayer = gradients.layers[i];

            var key = 'layer_${i}_weights';
            if (!m.exists(key)) {
                m.set(key, new Matrix(layer.weights.rows, layer.weights.cols));
                v.set(key, new Matrix(layer.weights.rows, layer.weights.cols));
            }

            var mW = m.get(key);
            var vW = v.get(key);

            for (r in 0...layer.weights.rows) {
                for (c in 0...layer.weights.cols) {
                    var g = gradLayer.weights.data[r][c];
                    mW.data[r][c] = beta1 * mW.data[r][c] + (1 - beta1) * g;
                    vW.data[r][c] = beta2 * vW.data[r][c] + (1 - beta2) * g * g;

                    layer.weights.data[r][c] -= lrT * mW.data[r][c] / (Math.sqrt(vW.data[r][c]) + epsilon);
                }
            }
        }
    }
}

class TrainingDataset {
    public var samples:Array<{input:haxe.ds.Vector<Float>, target:haxe.ds.Vector<Float>}>;

    public function new() {
